var t=`1067-laksa-katong`;var s=`world-1067`;var n=`SG`;var a=`southeast-asia`;var r=4;var o=39;var l={en:`Laksa Katong`,ua:`Лакса катонг`};var g={en:`Laksa Katong is a dish from Singapore prepared with thai red curry paste, shrimp paste, coconut milk, shrimp. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Лакса катонг, страва кухні країни Сінгапур, яку готують із таких продуктів: червона тайська паста карі, креветкова паста, кокосове молоко, креветка. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var m=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 7 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 7 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:7,i:[[`thai-red-curry-paste`,85,`g`],[`shrimp-paste`,18,`g`],[`canola-oil`,35,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 22 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 22 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:22,i:[[`coconut-milk`,730,`ml`],[`shrimp-stock`,800,`ml`],[`shrimp`,420,`g`],[`fish-cake`,230,`g`]]},{en:`Cook the listed ingredients in simmering water for about 7 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 7 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:7,i:[[`rice-noodles`,430,`g`],[`water`,1e3,`ml`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:3,i:[[`mung-bean-sprouts`,160,`g`],[`cilantro`,20,`g`],[`serrano-pepper`,1,`pcs`]]}];var d={slug:t,id:s,country:`SG`,region:a,servings:4,minutes:39,title:l,text:g,steps:m};export{n as country,d as default,s as id,o as minutes,a as region,r as servings,t as slug,m as steps,g as text,l as title};